  P.push({
    id: "p-foreign-pop-culture", n: 29, type: "ADVANTAGE", domain: "culture", level: 'B2', schema: "tradition-progress", title: "Foreign popular culture",
    text: "In many countries, young people now follow music, films, fashion and online trends from abroad far more closely than the traditions of their own country. Some people welcome this as a sign of an open, connected world, while others fear the loss of local identity. Do the advantages of this development outweigh the disadvantages?",
    keyNouns: ["young", "culture", "tradition", "foreign"],
    vars: { C1: {
      core: { ok: "The predominance of foreign popular culture among the young over local tradition.", d: ["The globalisation of the film, music and entertainment industries across the whole world.", "The decline of traditional festivals in rural communities.", "The influence of social media on the mental health of teenagers."] },
      facetA: { ok: "The broadened horizons and language competence that foreign media cultivate.", d: ["The enjoyment that young people derive from following the lives of global celebrities.", "The gradual disappearance of local music and dress.", "The profits earned by the foreign companies that export their culture."] },
      mechA: { ok: "immersing adolescents in languages, ideas and creative styles that domestic media rarely carry", d: ["surrounding teenagers with the lives of the foreign celebrities they follow online every day", "acquiring fluent English or Korean from lyrics, subtitles and online fan communities", "persuading young consumers to purchase imported clothing and merchandise"] },
      exA: { ok: "Teenagers who acquire fluent English or Korean from lyrics, subtitles and fan communities.", d: ["Teenagers who study a foreign language for three years at school without reaching fluency.", "Cinemas that screen foreign films in preference to domestic productions.", "The concerts of international artists that sell out within minutes."] },
      nuanceA: { ok: "most of what young people consume is entertainment designed to sell rather than culture chosen for its merit", d: ["foreign media teach young people nothing whatever that a good school could not teach them far better and far more cheaply", "subtitled films are watched far more widely than dubbed ones", "fan communities frequently bring together young people from dozens of countries"] },
      facetB: { ok: "The interrupted transmission of local traditions from one generation to the next.", d: ["The complete disappearance of every local tradition within the space of a single generation.", "The commercial pressure on domestic artists to imitate foreign styles.", "The exposure of young viewers to values their parents reject."] },
      mechB: { ok: "crowding out the songs, festivals and crafts that survive only when the young take part in them", d: ["persuading parents that their own customs are old-fashioned and unworthy of teaching to their children", "leaving traditional music and dance troupes unable to recruit younger members", "concentrating what young people watch on a handful of global platforms"] },
      exB: { ok: "Traditional music and dance troupes that struggle to recruit younger members.", d: ["Traditional festivals that now attract record numbers of foreign tourists every year.", "Young fans who spend their savings on merchandise from overseas groups.", "Domestic pop groups that sing entirely in English."] },
      nuanceB: { ok: "young audiences often rediscover their own traditions later, blending them with global styles", d: ["no tradition, once abandoned by the young, has ever been successfully revived, however much money was spent on it", "traditional arts are already subsidised by most national governments", "elderly performers rarely have the means to train a new generation"] },
      position: { ok: "the advantages outweigh the disadvantages, provided that schools and families keep local traditions alive as well", d: ["the advantages and disadvantages are finely balanced, and the outcome depends on the individual", "the disadvantages outweigh the advantages, because no language skill compensates for the loss of a cultural identity", "governments should restrict the import of foreign entertainment to protect their own culture"] },
      rationale: { ok: "a culture that engages with the world grows, whereas one shielded from it merely survives", d: ["young people will always follow whatever is new and foreign, so any resistance is entirely pointless", "English is the language of international business and of higher education everywhere", "traditional arts attract tourists and therefore earn foreign currency"] } },
    B2: {
      core: { ok: "The preference of young people for foreign popular culture over local tradition.", d: ["The spread of the film, music and entertainment industries across the whole world.", "The decline of traditional festivals in country villages.", "The effect of social media on the mental health of teenagers."] },
      facetA: { ok: "The wider view of the world and language skills that foreign media give.", d: ["The enjoyment young people get from following the lives of global celebrities.", "The slow disappearance of local music and dress.", "The profits earned by the foreign companies that export their culture."] },
      mechA: { ok: "surrounding teenagers with languages, ideas and creative styles that local media rarely show", d: ["surrounding teenagers with the lives of the foreign celebrities they follow online every day", "becoming fluent in English or Korean from lyrics, subtitles and online fan groups", "persuading young customers to buy imported clothes and merchandise"] },
      exA: { ok: "Teenagers who become fluent in English or Korean from lyrics, subtitles and fan groups.", d: ["Teenagers who study a foreign language for three years at school without becoming fluent.", "Cinemas that show foreign films instead of local ones.", "The concerts of international artists that sell out in minutes."] },
      nuanceA: { ok: "most of what young people watch is entertainment made to sell rather than culture chosen for its quality", d: ["foreign media teach young people nothing whatever that a good school could not teach them far better and far more cheaply", "subtitled films are watched far more widely than dubbed ones", "fan groups often bring together young people from dozens of countries"] },
      facetB: { ok: "The break in the passing of local traditions from one generation to the next.", d: ["The complete disappearance of every local tradition within the space of a single generation.", "The pressure on local artists to copy foreign styles.", "The exposure of young viewers to values their parents reject."] },
      mechB: { ok: "pushing aside the songs, festivals and crafts that survive only when the young join in", d: ["persuading parents that their own customs are old-fashioned and not worth teaching to their children", "leaving traditional music and dance groups unable to find younger members", "controlling what young people watch through a few global platforms"] },
      exB: { ok: "Traditional music and dance groups that struggle to find younger members.", d: ["Traditional festivals that now attract record numbers of foreign tourists every year.", "Young fans who spend their savings on merchandise from overseas groups.", "Local pop groups that sing only in English."] },
      nuanceB: { ok: "young audiences often come back to their own traditions later, mixing them with global styles", d: ["no tradition that the young have abandoned has ever been brought back to life, however much money was spent on it", "traditional arts already receive money from most national governments", "elderly performers rarely have the means to train a new generation"] },
      position: { ok: "the advantages outweigh the disadvantages, as long as schools and families keep local traditions alive too", d: ["the advantages and disadvantages are evenly balanced, and the result depends on the individual", "the disadvantages outweigh the advantages, because no language skill makes up for the loss of a cultural identity", "governments should limit foreign entertainment to protect their own culture"] },
      rationale: { ok: "a culture that mixes with the world grows, while one protected from it only survives", d: ["young people will always follow whatever is new and foreign, so resisting is pointless", "English is the language of international business and of higher education everywhere", "traditional arts attract tourists and so earn foreign money"] } } },
    modelId: "m-foreign-pop-culture"
  });

